	function BeginAcceptingAsync($listenPort) {
		return chilkat::_obj(CkSshTunnel_BeginAcceptingAsync($this->_cPtr,$listenPort),'CkTask');
	}

	/**
	 * Disconnects active tunnel clients and stops the tunnel-manager thread.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#CloseTunnel
	 * @param bool $waitForThreads
	 * @return bool
	 */
	function CloseTunnel($waitForThreads) {
