	}

	/**
	 * Establishes the SSH connection that will carry tunneled traffic. This method   performs the TCP or proxy connection, the SSH protocol handshake, and host-key   negotiation, but it does not authenticate the SSH user.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#Connect
	 * @param ?string $hostname
	 * @param int $port
	 * @return bool
	 */
	function Connect($hostname,$port) {
		return CkSshTunnel_Connect($this->_cPtr,$hostname,$port);
	}

	/**
	 * Creates an asynchronous task to call the Connect method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#ConnectAsync
	 * @param ?string $hostname
	 * @param int $port
	 * @return ?CkTask
	 */
	function ConnectAsync($hostname,$port) {
		return chilkat::_obj(CkSshTunnel_ConnectAsync($this->_cPtr,$hostname,$port),'CkTask');
	}

	/**
	 * Connects to a second SSH server through the existing connected and authenticated   Ssh object supplied in ssh.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#ConnectThroughSsh
	 * @param CkSsh $ssh
	 * @param ?string $hostname
	 * @param int $port
	 * @return bool
	 */
	function ConnectThroughSsh($ssh,$hostname,$port) {
		return CkSshTunnel_ConnectThroughSsh($this->_cPtr,$ssh,$hostname,$port);
	}

	/**
	 * Creates an asynchronous task to call the ConnectThroughSsh method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#ConnectThroughSshAsync
	 * @param CkSsh $ssh
	 * @param ?string $hostname
	 * @param int $port
	 * @return ?CkTask
	 */
	function ConnectThroughSshAsync($ssh,$hostname,$port) {
		return chilkat::_obj(CkSshTunnel_ConnectThroughSshAsync($this->_cPtr,$ssh,$hostname,$port),'CkTask');
	}

	/**
	 * Continues a keyboard-interactive authentication exchange started by   StartKeyboardAuth.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#ContinueKeyboardAuth
	 * @param ?string $response
	 * @return ?string
	 */
	function continueKeyboardAuth($response) {
		return CkSshTunnel_continueKeyboardAuth($this->_cPtr,$response);
	}

	/**
	 * Creates an asynchronous task to call the ContinueKeyboardAuth method with the arguments provided.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#ContinueKeyboardAuthAsync
	 * @param ?string $response
	 * @return ?CkTask
	 */
	function ContinueKeyboardAuthAsync($response) {
		return chilkat::_obj(CkSshTunnel_ContinueKeyboardAuthAsync($this->_cPtr,$response),'CkTask');
	}

	/**
	 * Disconnects all active tunnel clients while leaving the local listener and SSH   connection available.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#DisconnectAllClients
	 * @param bool $waitForThreads
	 * @return bool
	 */
	function DisconnectAllClients($waitForThreads) {
		return CkSshTunnel_DisconnectAllClients($this->_cPtr,$waitForThreads);
	}

	/**
	 * Returns an XML snapshot describing the tunnel manager, SSH channels, and current   tunnel clients. The returned data is intended for diagnostics and monitoring.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#GetCurrentState
	 * @return ?string
	 */
	function getCurrentState() {
		return CkSshTunnel_getCurrentState($this->_cPtr);
	}

	/**
	 * Returns an XML snapshot describing the tunnel manager, SSH channels, and current   tunnel clients. The returned data is intended for diagnostics and monitoring.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#GetCurrentState
	 * @return ?string
	 */
	function currentState() {
		return CkSshTunnel_currentState($this->_cPtr);
	}

	/**
	 * Returns _TRUE_ when the SSH transport used by this tunnel is   connected; otherwise returns _FALSE_.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#IsSshConnected
	 * @return bool
	 */
	function IsSshConnected() {
		return CkSshTunnel_IsSshConnected($this->_cPtr);
	}

	/**
	 * Loads this object with the SshTunnel instance that initiated   the asynchronous operation represented by task.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#LoadTaskCaller
	 * @param CkTask $task
	 * @return bool
	 */
	function LoadTaskCaller($task) {
		return CkSshTunnel_LoadTaskCaller($this->_cPtr,$task);
	}

	/**
