		return CkSshTunnel_SetAllowedAlgorithms($this->_cPtr,$json);
	}

	/**
	 * Begins keyboard-interactive authentication for login.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkSshTunnelRef.html#StartKeyboardAuth
	 * @param ?string $login
	 * @return ?string
	 */
	function startKeyboardAuth($login) {
